pub fn __OSSetExceptionHandler<'a>(ctx: &'a Ctx, exception: u8, handler: FnPtr<'a>) -> FnPtr<'a> {
    let mut exception = exception;
    let mut handler = handler;
    let mut oldHandler: FnPtr<'a> = null(ctx);
    oldHandler = (Handle::add(
        statics::dolphin__os__OS::OSExceptionTable(ctx).get(),
        (exception as i32),
    ))
    .get();
    (Handle::add(
        statics::dolphin__os__OS::OSExceptionTable(ctx).get(),
        (exception as i32),
    ))
    .set(handler);
    return oldHandler;
}

pub fn __OSGetExceptionHandler<'a>(ctx: &'a Ctx, exception: u8) -> FnPtr<'a> {
    let mut exception = exception;
    return (Handle::add(
        statics::dolphin__os__OS::OSExceptionTable(ctx).get(),
        (exception as i32),
    ))
    .get();
}

pub fn __OSGetDIConfig<'a>(ctx: &'a Ctx) -> u32 {
    return ((Handle::add((ptr::<Val<'a, u32>>(ctx, 0xcc006000_u32 as u32)), 9_i32)).get()
        & (255_i32 as u32));
}

fn inl_OSGetConsoleType_unfused<'a>(ctx: &'a Ctx) -> u32 {
    if (!(!Handle::is_null(statics::dolphin__os__OS::BootInfo(ctx).get())))
        || ((statics::dolphin__os__OS::BootInfo(ctx).get()).consoleType() == (0_i32 as u32))
    {
        return (0x10000002_i32 as u32);
    }
    return (statics::dolphin__os__OS::BootInfo(ctx).get()).consoleType();
}

